def test_escape():
    pattern = re.compile(r"\\(\'|\"|\\|[abfnrtv]|x.{0,2}|[0-7]{1,3})")

    def m(s):
        match = pattern.match(s)
        assert match is not None, s
        return match

    # Simple escapes are looked up in simple_escapes.
    simple = {
        "a": "\a", "b": "\b", "f": "\f", "n": "\n",
        "r": "\r", "t": "\t", "v": "\v",
        "'": "'", '"': '"', "\\": "\\",
    }
    for tail, expected in simple.items():
        assert escape(m("\\" + tail)) == expected

    # Hex escapes.
    assert escape(m("\\x41")) == "A"
    assert escape(m("\\x7a")) == "z"
    assert escape(m("\\x00")) == "\x00"
    assert escape(m("\\xFF")) == "\xff"

    # Octal escapes.
    assert escape(m("\\0")) == "\x00"
    assert escape(m("\\7")) == "\x07"
    assert escape(m("\\101")) == "A"
